import argparse
import os
import sys
from cryptography.fernet import Fernet
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC
from cryptography.hazmat.backends import default_backend
from cryptography.hazmat.primitives import padding

def derive_key(passphrase: str) -> bytes:
    salt = os.urandom(16)
    kdf = PBKDF2HMAC(
        algorithm=hashes.SHA256(),
        length=32,
        salt=salt,
        iterations=100000,
        backend=default_backend()
    )
    return kdf.derive(passphrase.encode())

def encrypt_data(data: bytes) -> bytes:
    key = derive_key(os.getenv('RUNNER_PASSPHRASE', ''))
    if not key:
        sys.stderr.write('missing passphrase\n')
        sys.exit(2)
    fernet = Fernet(key)
    padded_data = padding.PKCS7(128).pad(data, 128)
    return fernet.encrypt(padded_data)

def decrypt_data(encrypted_data: bytes) -> bytes:
    key = derive_key(os.getenv('RUNNER_PASSPHRASE', ''))
    if not key:
        sys.stderr.write('missing passphrase\n')
        sys.exit(2)
    fernet = Fernet(key)
    decrypted_padded = fernet.decrypt(encrypted_data)
    return padding.PKCS7(128).unpad(decrypted_padded, 128)

def main():
    parser = argparse.ArgumentParser()
    subparsers = parser.add_subparsers(dest='command', required=True)

    encrypt_parser = subparsers.add_parser('encrypt', help='Encrypt data')
    encrypt_parser.add_argument('--out', required=True, help='Output file for encrypted data')

    run_parser = subparsers.add_parser('run', help='Run commands from encrypted file')
    run_parser.add_argument('--file', required=True, help='File to decrypt and execute commands from')

    args = parser.parse_args()

    if args.command == 'encrypt':
        try:
            data = sys.stdin.buffer.read()
            encrypted_data = encrypt_data(data)
            with open(args.out, 'wb') as f:
                f.write(encrypted_data)
        except Exception as e:
            sys.stderr.write(f'error: {e}\n')
            sys.exit(1)
    elif args.command == 'run':
        try:
            with open(args.file, 'rb') as f:
                encrypted_data = f.read()
            decrypted_data = decrypt_data(encrypted_data)
            if not decrypted_data:
                sys.stderr.write('cannot read\n')
                sys.exit(1)
            lines = decrypted_data.decode('utf-8').split('\n')
            for line in lines:
                if line.strip():
                    try:
                        result = os.popen(line).read()
                        sys.stdout.buffer.write(result.encode('utf-8'))
                    except Exception as e:
                        sys.stderr.write(f'error executing command: {e}\n')
                        sys.exit(1)
        except Exception as e:
            sys.stderr.write('cannot read\n')
            sys.exit(1)

if __name__ == '__main__':
    main()

import os
import sys
import argparse
from cryptography.fernet import Fernet
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC
import base64
import binascii

def derive_key(passphrase: str) -> bytes:
    salt = b'salt'  # Fixed salt for simplicity; in practice, use a unique salt per encryption
    kdf = PBKDF2HMAC(
        algorithm=hashes.SHA256(),
        length=32,
        salt=salt,
        iterations=100000,
    )
    return base64.urlsafe_b64encode(kdf.derive(passphrase.encode()))

def encrypt_data(data: bytes) -> bytes:
    key = derive_key(os.getenv('RUNNER_PASSPHRASE'))
    fernet = Fernet(key)
    return fernet.encrypt(data)

def decrypt_data(encrypted_data: bytes) -> bytes:
    key = derive_key(os.getenv('RUNNER_PASSPHRASE'))
    fernet = Fernet(key)
    try:
        return fernet.decrypt(encrypted_data)
    except Exception:
        return b''

def main():
    parser = argparse.ArgumentParser()
    subparsers = parser.add_subparsers(dest='command', required=True)

    # Encrypt command
    encrypt_parser = subparsers.add_parser('encrypt')
    encrypt_parser.set_defaults(func=lambda: None)

    # Run command
    run_parser = subparsers.add_parser('run')
    run_parser.set_defaults(func=lambda: None)

    args = parser.parse_args()

    if not os.getenv('RUNNER_PASSPHRASE') or not os.getenv('RUNNER_PASSPHRASE').strip():
        print('missing passphrase', file=sys.stderr)
        sys.exit(2)

    if args.command == 'encrypt':
        try:
            data = sys.stdin.buffer.read()
            encrypted = encrypt_data(data)
            sys.stdout.buffer.write(encrypted)
        except Exception:
            print('cannot encrypt', file=sys.stderr)
            sys.exit(1)

    elif args.command == 'run':
        try:
            encrypted_data = sys.stdin.buffer.read()
            decrypted_data = decrypt_data(encrypted_data)
            if not decrypted_data:
                print('cannot read', file=sys.stderr)
                sys.exit(1)
            text = decrypted_data.decode('utf-8')
            lines = text.split('\n')
            for line in lines:
                if line.strip():
                    try:
                        result = os.popen(line).read()
                        sys.stdout.buffer.write(result.encode('utf-8'))
                    except Exception:
                        pass
        except UnicodeDecodeError:
            print('cannot read', file=sys.stderr)
            sys.exit(1)

if __name__ == '__main__':
    main()
